(ROOT/'004-workspace.sql').write_text(prefix+contract+(ROOT/'templates/workspace-validation.sql').read_text()+fullnormalize+fullcurrent+fullcommand+"\nREVOKE ALL ON ALL FUNCTIONS IN SCHEMA wjb_migration FROM PUBLIC,anon,authenticated,service_role;\nCOMMIT;\n")
